320	        if (customerRepository.existsByEmailIgnoreCase(request.email())) {
321	            throw emailAlreadyExists(request.email());
322	        }
323	        Customer customer = customerRepository.save(CustomerMapper.toEntity(request));
324	        return CustomerMapper.toResponse(customer);
325	    }
326	
327	    @Transactional
328	    public CustomerResponse update(Long id, CustomerRequest request) {
329	        Customer customer = getCustomer(id);
330	        if (customerRepository.existsByEmailIgnoreCaseAndIdNot(request.email(), id)) {
331	            throw emailAlreadyExists(request.email());
332	        }
333	        CustomerMapper.updateEntity(customer, request);
334	        return CustomerMapper.toResponse(customerRepository.save(customer));
335	    }
