878	import { Injectable, Signal, inject } from '@angular/core';
879	import { Observable } from 'rxjs';
880	
881	export interface Customer {
882	  id: number;
883	  firstName: string;
884	  lastName: string;
885	  email: string;
886	  phone: string;
887	  nip: string | null;
888	}
