890	export type CustomerRequest = Omit<Customer, 'id'>;
891	
892	@Injectable({ providedIn: 'root' })
893	export class CustomerApi {
894	  private readonly http = inject(HttpClient);
895	  private readonly url = '/api/customers';
896	
897	  list() {
898	    return httpResource<Customer[]>(() => this.url, { defaultValue: [] });
899	  }
900	
901	  get(id: Signal<number | undefined>) {
902	    return httpResource<Customer>(() => {
903	      const customerId = id();
904	      return customerId === undefined ? undefined : `${this.url}/${customerId}`;
905	    });
906	  }
907	
908	  create(request: CustomerRequest): Observable<Customer> {
909	    return this.http.post<Customer>(this.url, request);
910	  }
911	
912	  update(id: number, request: CustomerRequest): Observable<Customer> {
913	    return this.http.put<Customer>(`${this.url}/${id}`, request);
914	  }
915	
916	  delete(id: number): Observable<void> {
917	    return this.http.delete<void>(`${this.url}/${id}`);
918	  }
