@Service
@Transactional(readOnly = true)
public class VehicleService {

    private final VehicleRepository vehicleRepository;

    public VehicleService(VehicleRepository vehicleRepository) {
        this.vehicleRepository = vehicleRepository;
    }

    public List<VehicleResponse> findAll() {
        return vehicleRepository.findAll(Sort.by("id")).stream()
                .map(VehicleMapper::toResponse)
                .toList();
    }

    public VehicleResponse findById(Long id) {
        return VehicleMapper.toResponse(getVehicle(id));
    }

    @Transactional
    public VehicleResponse create(VehicleRequest request) {
        if (vehicleRepository.existsByVin(request.vin())) {
            throw vinAlreadyExists(request.vin());
        }
        Vehicle vehicle = vehicleRepository.save(VehicleMapper.toEntity(request));
        return VehicleMapper.toResponse(vehicle);
    }

    @Transactional
    public VehicleResponse update(Long id, VehicleRequest request) {
        Vehicle vehicle = getVehicle(id);
        if (vehicleRepository.existsByVinAndIdNot(request.vin(), id)) {
            throw vinAlreadyExists(request.vin());
        }
        VehicleMapper.updateEntity(vehicle, request);
        return VehicleMapper.toResponse(vehicleRepository.save(vehicle));
    }

    @Transactional
    public void delete(Long id) {
        vehicleRepository.delete(getVehicle(id));
    }

    private Vehicle getVehicle(Long id) {
        return vehicleRepository.findById(id)
                .orElseThrow(() -> new NotFoundException("Vehicle with id " + id + " not found"));
    }

    private static ConflictException vinAlreadyExists(String vin) {
        return new ConflictException("Vehicle with VIN " + vin + " already exists");
    }
}
package com.example.dealership.vehicle;

public final class VehicleMapper {

    private VehicleMapper() {
    }

    public static Vehicle toEntity(VehicleRequest request) {
        return new Vehicle(
                request.vin(),
                request.make(),
                request.model(),
                request.productionYear(),
                request.fuelType(),
                request.plannedHandoverDate());
    }

    public static void updateEntity(Vehicle vehicle, VehicleRequest request) {
        vehicle.setVin(request.vin());
        vehicle.setMake(request.make());
        vehicle.setModel(request.model());
        vehicle.setProductionYear(request.productionYear());
        vehicle.setFuelType(request.fuelType());
        vehicle.setPlannedHandoverDate(request.plannedHandoverDate());
    }

    public static VehicleResponse toResponse(Vehicle vehicle) {
        return new VehicleResponse(
                vehicle.getId(),
                vehicle.getVin(),
                vehicle.getMake(),
                vehicle.getModel(),
                vehicle.getProductionYear(),
                vehicle.getFuelType(),
                vehicle.getPlannedHandoverDate());
    }
}
import { Component, inject, signal } from '@angular/core';
import { RouterLink } from '@angular/router';
import { firstValueFrom } from 'rxjs';
import { loadErrorMessage, problemDetailMessage } from '../shared/problem-detail';
import { FUEL_TYPE_LABELS, Vehicle, VehicleApi } from './vehicle-api';

@Component({
  selector: 'app-vehicle-list',
  imports: [RouterLink],
  templateUrl: './vehicle-list.html',
})
export class VehicleList {
  private readonly vehicleApi = inject(VehicleApi);

  protected readonly vehicles = this.vehicleApi.list();
  protected readonly fuelTypeLabels = FUEL_TYPE_LABELS;
  protected readonly deleteError = signal<string | null>(null);

  protected loadError(error: unknown): string {
    return loadErrorMessage(error, 'Vehicles not found');
  }

  protected async delete(vehicle: Vehicle): Promise<void> {
    this.deleteError.set(null);
    try {
      await firstValueFrom(this.vehicleApi.delete(vehicle.id));
      this.vehicles.reload();
    } catch (error) {
      this.deleteError.set(problemDetailMessage(error));
    }
  }
}
<h1>Vehicles</h1>

<p><a routerLink="/vehicles/new">Add vehicle</a></p>

@if (deleteError(); as message) {
  <p class="error" role="alert">{{ message }}</p>
}

@if (vehicles.isLoading()) {
  <p>Loading…</p>
} @else if (vehicles.error(); as error) {
  <p class="error" role="alert">{{ loadError(error) }}</p>
} @else if (vehicles.value(); as vehicles) {
  <table>
    <thead>
      <tr>
        <th>VIN</th>
        <th>Make</th>
        <th>Model</th>
        <th>Production year</th>
        <th>Fuel type</th>
        <th>Planned handover</th>
        <th>Actions</th>
      </tr>
    </thead>
    <tbody>
      @for (vehicle of vehicles; track vehicle.id) {
        <tr>
          <td>
            <a [routerLink]="['/vehicles', vehicle.id]">{{ vehicle.vin }}</a>
          </td>
          <td>{{ vehicle.make }}</td>
          <td>{{ vehicle.model }}</td>
          <td>{{ vehicle.productionYear }}</td>
          <td>{{ fuelTypeLabels[vehicle.fuelType] }}</td>
          <td>{{ vehicle.plannedHandoverDate ?? '—' }}</td>
          <td>
            <a [routerLink]="['/vehicles', vehicle.id, 'edit']">Edit</a>
            <button type="button" (click)="delete(vehicle)">Delete</button>
          </td>
        </tr>
      } @empty {
        <tr>
          <td colspan="7">No vehicles yet.</td>
        </tr>
      }
    </tbody>
  </table>
}
